using System.Text.Json;
using MatterFlow.Configuration.Contracts;
using Shouldly;

namespace MatterFlow.UnitTests.Configuration;

/// <summary>The Task Type icon allow-list (contracts/task-type-icons.json, generated by tools/icons and shared with the Angular library).</summary>
public class TaskTypeIconsTests
{
    [Fact]
    public void The_default_icon_is_file_text_and_is_in_the_library()
    {
        TaskTypeIcons.DefaultKey.ShouldBe("file-text");
        TaskTypeIcons.IsValid(TaskTypeIcons.DefaultKey).ShouldBeTrue();
    }

    [Fact]
    public void The_library_has_250_to_300_unique_kebab_case_keys_that_fit_the_column()
    {
        var keys = TaskTypeIcons.All.Select(i => i.Key).ToList();
        keys.Count.ShouldBeInRange(250, 300);
        keys.Distinct().Count().ShouldBe(keys.Count);
        keys.ShouldAllBe(k => k.Length <= 50 && System.Text.RegularExpressions.Regex.IsMatch(k, "^[a-z0-9]+(-[a-z0-9]+)*$"));
        TaskTypeIcons.All.ShouldAllBe(i => i.Label.Length > 0);
    }

    [Fact]
    public void Every_category_of_the_spec_is_present_and_every_icon_belongs_to_one()
    {
        string[] expected = ["General", "Identification", "Preservation", "Collection", "Processing", "Review", "Analysis", "Production", "Presentation", "Data & systems", "Communication", "Admin"];
        TaskTypeIcons.All.Select(i => i.Category).Distinct().Order().ShouldBe(expected.Order());
    }

    [Theory]
    [InlineData("file-text", true)]
    [InlineData("mail", true)]
    [InlineData("File-Text", false)]
    [InlineData("file-text ", false)]
    [InlineData("", false)]
    [InlineData(null, false)]
    [InlineData("nope", false)]
    public void Only_exact_library_keys_are_valid(string? key, bool valid) => TaskTypeIcons.IsValid(key).ShouldBe(valid);

    [Fact]
    public void The_embedded_list_is_the_contract_file_in_the_repository()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "..", "contracts", "task-type-icons.json");
        using var doc = JsonDocument.Parse(File.ReadAllText(Path.GetFullPath(path)));
        var onDisk = doc.RootElement.GetProperty("icons").EnumerateArray().Select(i => i.GetProperty("key").GetString()!).Order().ToList();
        onDisk.ShouldBe(TaskTypeIcons.All.Select(i => i.Key).Order().ToList());
    }
}
